# Remove friends on Venmo who are not in contacts anymore (by email)
for email in emails_to_remove:
    apis.venmo.remove_friend(access_token=venmo_token, email=email)

# Remove friends on Venmo who are not in contacts anymore (by phone)
for phone in phones_to_remove:
    apis.venmo.remove_friend(access_token=venmo_token, phone_number=phone)

# Add friends on Venmo who are in phone friends but not in Venmo friends
for email in to_add:
    apis.venmo.add_friend(user_email=email, access_token=venmo_access_token)

# Remove friends on Venmo who are not in phone friends but are in Venmo friends
for email in to_remove:
    apis.venmo.remove_friend(user_email=email, access_token=venmo_access_token)

# Add friends on Venmo who are in phone friends but not in Venmo friends
for email in to_add:
    apis.venmo.add_friend(user_email=email, access_token=venmo_access_token)

# Remove friends on Venmo who are not in phone friends but are in Venmo friends
for email in to_remove:
    apis.venmo.remove_friend(user_email=email, access_token=venmo_access_token)

# Extract emails of contacts who have "friend" in their relationships to consider as friends in phone contacts
phone_friends_emails = set()
for contact in contacts:
    if "friend" in contact.get("relationships", []):
        email = contact.get("email")
        if email:
            phone_friends_emails.add(email.lower())

# Extract emails of current venmo friends
venmo_friends_emails = set()
for friend in venmo_friends:
    email = friend.get("email")
    if email:
        venmo_friends_emails.add(email.lower())

phone_friends_emails, venmo_friends_emails

# We need to add friends in to_add and remove friends in to_remove on Venmo.
# For adding and removing, we need the friend_id from venmo_friends for removal,
# and for adding, we only need the email.

# Create a mapping from email to friend_id for venmo friends
email_to_friend_id = {friend["email"].lower(): friend["friend_id"] for friend in venmo_friends if "email" in friend and "friend_id" in friend}

# Remove friends who are not in phone friends
for email in to_remove:
    friend_id = email_to_friend_id.get(email)
    if friend_id:
        apis.venmo.remove_friend(access_token=venmo_token, friend_id=friend_id)

# Add friends who are in phone friends but not in venmo friends
for email in to_add:
    apis.venmo.add_friend(access_token=venmo_token, email=email)

# The error indicates some emails in to_add are not valid email addresses.
# Let's filter to_add to only include valid emails (contain '@' and a dot after '@') before adding.

def is_valid_email(email):
    if '@' in email:
        local, _, domain = email.partition('@')
        if '.' in domain and local and domain:
            return True
    return False

valid_to_add = [email for email in to_add if is_valid_email(email)]

# Retry adding only valid emails
for email in valid_to_add:
    apis.venmo.add_friend(access_token=venmo_token, email=email)

# Extract emails of contacts who have "friend" in their relationships to consider as friends to sync with Venmo
friend_emails = set()
for contact in contacts:
    if "friend" in contact.get("relationships", []):
        email = contact.get("email")
        if email:
            friend_emails.add(email.lower())

# Extract emails of current Venmo friends
venmo_friend_emails = set()
for friend in venmo_friends:
    email = friend.get("email")
    if email:
        venmo_friend_emails.add(email.lower())

friend_emails, venmo_friend_emails

